-- A client's own payment terms in days; NULL means invoices are due at the end of the following month.
ALTER TABLE client ADD COLUMN terms_days INT;
-- A draft's percentage discount off its subtotal, 0 to 100 with up to two decimals; 0 is none.
ALTER TABLE invoice ADD COLUMN discount_pct DECIMAL(5, 2) DEFAULT 0 NOT NULL;
package net.officefloor.hq.app.clients;

import jakarta.validation.Valid;
import jakarta.validation.constraints.Email;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.util.List;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/clients")
public class ClientController {

    public record ClientView(Long id, String name, String email, Integer termsDays) {
        static ClientView of(Client c) {
            return new ClientView(c.getId(), c.getName(), c.getEmail(), c.getTermsDays());
        }
    }

    public record NewClient(
            @NotBlank(message = "Enter the client's name.")
            @Size(max = 255, message = "The name must be at most 255 characters.")
            String name,
            @NotBlank(message = "Enter the client's email address.")
            @Email(regexp = PROPER_EMAIL,
                    message = "Enter a proper email address, like name@company.com.")
            @Size(max = 255, message = "The email must be at most 255 characters.")
            String email,
            @Min(value = 1, message = "Payment terms must be from 1 to 365 days.")
            @Max(value = 365, message = "Payment terms must be from 1 to 365 days.")
            Integer termsDays) {
    }

    /**
     * A proper email address: a mailbox, an @, and a domain with at least one dot whose parts are
     * not empty — so name@company.com, but not name@company (a typo) or name.company.com.
     */
    static final String PROPER_EMAIL = "\\s*[^@\\s]+@[^@\\s.]+(\\.[^@\\s.]+)+\\s*";

    private final ClientService clients;

    public ClientController(ClientService clients) {
        this.clients = clients;
    }

    @GetMapping
    public List<ClientView> list() {
        return clients.list().stream().map(ClientView::of).toList();
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public ClientView add(@Valid @RequestBody NewClient body) {
        return ClientView.of(clients.add(body.name(), body.email(), body.termsDays()));
    }
}
package net.officefloor.hq.app.clients;

import java.util.Comparator;
import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

/** Turns a refused client into a problem response whose detail says what is wrong. */
@RestControllerAdvice(assignableTypes = ClientController.class)
public class ClientErrors {

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ProblemDetail invalid(MethodArgumentNotValidException e) {
        String detail = e.getBindingResult().getFieldErrors().stream()
                .sorted(Comparator.comparing(f -> f.getField().equals("name") ? 0 : 1))
                .map(f -> f.getDefaultMessage())
                .distinct()
                .reduce((a, b) -> a + " " + b)
                .orElse("The client is not valid.");
        return ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST, detail);
    }

    @ExceptionHandler(ClientRejectedException.class)
    public ProblemDetail rejected(ClientRejectedException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.CONFLICT, e.getMessage());
    }
}
package net.officefloor.hq.app.clients;

import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/** A client invoices are raised for. */
@Entity
@Table(name = "client")
public class Client {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String name;

    private String email;

    /** Payment terms in days; null means the usual end of the following month. */
    private Integer termsDays;

    protected Client() {
    }

    public Client(String name, String email, Integer termsDays) {
        this.name = name;
        this.email = email;
        this.termsDays = termsDays;
    }

    public Long getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    public String getEmail() {
        return email;
    }

    public Integer getTermsDays() {
        return termsDays;
    }
}
package net.officefloor.hq.app.clients;

/** A client that cannot be saved; the message says why, in words the user can act on. */
public class ClientRejectedException extends RuntimeException {

    public ClientRejectedException(String message) {
        super(message);
    }
}
package net.officefloor.hq.app.clients;

import org.springframework.data.jpa.repository.JpaRepository;

public interface ClientRepository extends JpaRepository<Client, Long> {

    boolean existsByEmailIgnoreCase(String email);
}
package net.officefloor.hq.app.clients;

import java.util.Comparator;
import java.util.List;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Lists and adds clients. Clients are listed A to Z by name, ignoring capitals. No two clients share
 * an email address, ignoring capitals.
 */
@Service
public class ClientService {

    static final Comparator<Client> BY_NAME = Comparator
            .comparing(Client::getName, String.CASE_INSENSITIVE_ORDER)
            .thenComparing(Client::getName)
            .thenComparing(Client::getId);

    private final ClientRepository clients;

    public ClientService(ClientRepository clients) {
        this.clients = clients;
    }

    @Transactional(readOnly = true)
    public List<Client> list() {
        return clients.findAll().stream().sorted(BY_NAME).toList();
    }

    @Transactional
    public Client add(String name, String email, Integer termsDays) {
        String address = email.trim();
        if (clients.existsByEmailIgnoreCase(address)) {
            throw new ClientRejectedException("Another client already has the email " + address + ".");
        }
        return clients.save(new Client(name.trim(), address, termsDays));
    }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';

export interface Client {
  id: number;
  name: string;
  email: string;
  // Payment terms in days; null means due at the end of the month after issue.
  termsDays: number | null;
}

export type NewClient = Omit<Client, 'id'>;

// The clients REST API.
@Injectable({ providedIn: 'root' })
export class ClientService {
  private readonly http = inject(HttpClient);

  list(): Observable<Client[]> {
    return this.http.get<Client[]>('/api/clients');
  }

  add(client: NewClient): Observable<Client> {
    return this.http.post<Client>('/api/clients', client);
  }
}

// Clients A to Z by name, ignoring capitals — the same order the server lists them in.
export function byName(a: Client, b: Client): number {
  const x = a.name.toLowerCase();
  const y = b.name.toLowerCase();
  return x < y ? -1 : x > y ? 1 : a.name < b.name ? -1 : a.name > b.name ? 1 : a.id - b.id;
}
import { Component, computed, inject, signal } from '@angular/core';
import { HttpErrorResponse } from '@angular/common/http';
import { FormControl, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { ClientInvoices } from '../invoices/client-invoices';
import { money } from '../invoices/invoice-format';
import { ClientBalance, InvoiceService } from '../invoices/invoice.service';
import { Client, ClientService, byName } from './client.service';

// A proper email address: a mailbox, an @, and a domain with at least one dot — name@company.com,
// not name@company (a typo). The same rule the server applies.
const PROPER_EMAIL = /^[^@\s]+@[^@\s.]+(\.[^@\s.]+)+$/;

// The workspace's clients: listed A to Z by name (ignoring capitals), with a form to add one.
// Clicking a client lists that client's invoices beside the clients. Typing an invoice number into
// the lookup box selects its client and opens the invoice; a mistyped number opens nothing.
@Component({
  selector: 'app-clients',
  imports: [ReactiveFormsModule, ClientInvoices],
  styles: `
    :host {
      display: flex;
      flex-wrap: wrap;
      gap: 2rem;
      align-items: flex-start;
    }
    .client {
      display: flex;
      gap: 1rem;
      width: 100%;
      text-align: left;
      font: inherit;
      color: inherit;
      background: none;
      border: 1px solid transparent;
      padding: 0.25rem 0.5rem;
      cursor: pointer;
    }
    .client[aria-pressed='true'] {
      border-color: currentColor;
      font-weight: bold;
    }
  `,
  template: `
    <section aria-labelledby="clients-heading">
      <form [formGroup]="lookup" (ngSubmit)="findInvoice()" aria-label="Open an invoice" novalidate>
        <label for="invoice-lookup">Invoice number</label>
        <input
          id="invoice-lookup"
          data-testid="invoice-lookup-input"
          formControlName="number"
          placeholder="INV-0000075"
          required
        />
        <button type="submit" data-testid="invoice-lookup-submit" [disabled]="looking()">
          Open invoice
        </button>
        @if (lookupError()) {
          <p role="alert" data-testid="invoice-lookup-error">{{ lookupError() }}</p>
        }
      </form>

      <h2 id="clients-heading">Clients</h2>

      <ul data-testid="client-list">
        @for (c of clients(); track c.id) {
          <li [attr.data-testid]="'client-row-' + c.id" (click)="selectClient(c.id)">
            <button
              type="button"
              class="client"
              [attr.aria-pressed]="selectedId() === c.id"
              (click)="$event.stopPropagation(); selectClient(c.id)"
            >
              <span data-testid="client-name">{{ c.name }}</span>
